(port) => {
    /*
      require('net')
        .createServer()
        .on('listening', () => process.exit(0))
        .on('error', () => process.exit(1))
        .listen(+process.env.PORT)
      */
    const r = spawnSync(process.execPath, [
        '-e',
        `require("net").createServer().on("listening",()=>process.exit(0)).on("error",()=>process.exit(1)).listen(+process.env.PORT)`,
    ], {
        env: {
            ...process.env,
            PORT: String(port),
            NODE_OPTIONS: undefined,
            ELECTRON_RUN_AS_NODE: '1',
        },
    });
    return r.status === 0;
}

async (browserURL, cancellationToken, logger, remoteHostHeader) => {
    while (true) {
        try {
            return await getWSEndpoint(browserURL, cancellationToken, logger, isNode, remoteHostHeader);
        }
        catch (e) {
            if (cancellationToken.isCancellationRequested) {
                throw new Error(`Could not connect to debug target at ${browserURL}: ${e.message}`);
            }
            await delay(200);
        }
    }
}

