async (params, token) => {
        const languageClient = await getActiveLanguageClient();
        if (!languageClient) {
            return [];
        }
        if (token !== undefined) {
            return languageClient.sendRequest(DocumentSymbolRequest.type, params, token);
        }
        return languageClient.sendRequest(DocumentSymbolRequest.type, params);
    }

async (params, token) => {
        const languageClient = await getActiveLanguageClient();
        if (!languageClient) {
            return null;
        }
        if (token !== undefined) {
            return languageClient.sendRequest(DefinitionRequest.type, params, token);
        }
        return languageClient.sendRequest(DefinitionRequest.type, params);
    }

